sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // if(!g_form.isLiveUpdating()){ 
 //   var dynamic_query = g_scratchpad.query;
 //   var rows = g_scratchpad.rows;

    var host = g_scratchpad.host;
    var assign = g_form.getValue('assigned_to');
    var stat = g_form.getValue('state');

    // When Lock becomes false by scheduledJob.

    if ((newValue == 'false') && (assign == "") && (stat == '1')) {
        var ans = confirm('Due to the inactivity, the current bulk task is unlocked and unassigned');
        if (ans) {

            // Redirect to Bulk List view.

            var url = host + "x_hsb11_mss_c_proc_mss_custody_task_list.do?&sysparm_query=active=true^bulk_id.numberISNOTEMPTY^GROUPBYbulk_id";
            top.window.location = url;
        } else {

           // Redirect to Bulk List view.

            url = host + "x_hsb11_mss_c_proc_mss_custody_task_list.do?&sysparm_query=active=true^bulk_id.numberISNOTEMPTY^GROUPBYbulk_id";
            top.window.location = url;
        }
    }
} //}
